<script lang="ts">
  import { slide } from "svelte/transition";
  import { flip } from "svelte/animate";
  import { createEventDispatcher, onDestroy, onMount } from "svelte";

  import Plugin from "./Plugin.svelte";
  import Cover from "./Cover.svelte";
  import Total from "./TotalAccuracy.svelte";
  import MiniProfile from "../components/MiniProfile.svelte";
  import { fade } from "../slidinghud";

  import { NpcFeatureType, RangeType, WeaponType } from "../../enums";
  import { WeaponRangeTemplate } from "../../canvas/weapon-range-template";
  import { targetsFromTemplate } from "../../flows/_template";
  import HudCheckbox from "../components/HudCheckbox.svelte";
  import { LancerToken } from "../../token";
  import AccDiffInput from "./AccDiffInput.svelte";
  import { type AccDiffHudData } from "./data.svelte";
  import { tokenDocFromUuidSync } from "../../util/misc";

  /* ===== PROPS ===== */

  let {
    data,
    kind,
    // TODO: remove event dispatcher, use callback props instead
    // cancel,
    // submit,
  }: {
    data: AccDiffHudData;
    kind: "hase" | "attack";
    // cancel: Function;
    // submit: Function;
  } = $props();

  /* ===== STATE ===== */

  const dispatch = createEventDispatcher();
  let submitted = $state(false);
  const hookCallbacks: Record<string, number> = {};

  /* ===== DERIVED VALUES ===== */

  const title = $derived(data.title);
  const lancerItem = $derived(data.lancerItem);
  const lancerActor = $derived(data.lancerActor);
  const base = $derived(data.base);
  const weapon = $derived(data.weapon);
  const targets = $derived(data.targets);

  const rollerName = $derived(lancerActor ? ` -- ${lancerActor.token?.name || lancerActor.name}` : "");
  const profile = $derived(lancerItem ? findProfile() : null);
  const ranges = $derived(lancerItem ? findRanges() : null);
  const useCover = $derived(!(isTech() || (isMelee() && !weapon.thrown)));
  const flatTotal = $derived(kind === "attack" ? base.grit + base.flatBonus : 0);

  const accWeaponPlugins = $derived(Object.values(weapon.plugins).filter(plugin => plugin.category === "acc"));
  const diffWeaponPlugins = $derived(Object.values(weapon.plugins).filter(plugin => plugin.category === "diff"));
  const accTargetPlugins = $derived(
    targets.length === 1 ? Object.values(targets[0].plugins).filter(plugin => plugin.category === "acc") : []
  );
  const diffTargetPlugins = $derived(
    targets.length === 1 ? Object.values(targets[0].plugins).filter(plugin => plugin.category === "diff") : []
  );

  /* ===== FUNCTIONS ===== */

  onMount(() => {
    // Register hook callbacks for updating targeted tokens
    hookCallbacks.targetToken = Hooks.on("targetToken", (user, _token, _isNewTarget) => {
      if (user.isSelf) {
        updateTargets();
      }
    });
    hookCallbacks.createActiveEffect = Hooks.on("createActiveEffect", updateTargets);
    hookCallbacks.deleteActiveEffect = Hooks.on("deleteActiveEffect", updateTargets);
    // updateToken triggers on things like token movement (spotter) and probably a lot of other things
    hookCallbacks.updateToken = Hooks.on("updateToken", token => {
      // If there's an animation, update when it finishes, otherwise just update
      // @ts-expect-error v13 types
      token.object.movementAnimationPromise?.then(updateTargets);
    });
  });

  onDestroy(() => {
    // Unregister hook callbacks
    for (const key in hookCallbacks) {
      Hooks.off(key, hookCallbacks[key]);
    }
  });

  $effect(() => {
    data.hydrate(data.lancerItem || data.lancerActor);

    // Initialize engaged
    if (kind === "attack" && lancerItem && !isTech()) {
      let ranges: RangeType[] = [];
      if (
        lancerItem.is_pilot_weapon() ||
        (lancerItem.is_npc_feature() && lancerItem.system.type === NpcFeatureType.Weapon)
      ) {
        ranges = lancerItem.system.range.map(r => r.type);
      } else if (lancerItem.is_mech_weapon()) {
        ranges = (lancerItem.system.active_profile?.range || []).map(r => r.type);
      }
      // If the weapon has any range type other than Threat or Thrown, it is affected by engaged.
      if (ranges.some(r => ![RangeType.Threat, RangeType.Thrown].includes(r))) {
        weapon.engaged = !!weapon.engagedStatus;
      }
    }
  });

  function focus(el: HTMLElement) {
    el.focus();
  }

  function updateTargets() {
    if (!data) return;
    data.replaceTargets(Array.from(game!.user!.targets).map(t => t.document.uuid));
  }

  function targetHoverIn(event: MouseEvent, targetUuid: string) {
    const target = tokenDocFromUuidSync(targetUuid, { strict: true })?.object;
    if (!target) return;
    // Ignore target hovering after the form has been submitted, to avoid flickering when
    // the UI slides down.
    if (submitted) return;
    const thtModule = game.modules.get("terrain-height-tools");
    if (!thtModule?.active || foundry.utils.isNewerVersion("0.3.3", thtModule.version)) {
      // @ts-expect-error not supposed to use a private method
      target._onHoverIn(event);
    } else {
      drawLos(target);
    }
  }

  function targetHoverOut(event: MouseEvent, targetUuid: string) {
    const target = tokenDocFromUuidSync(targetUuid, { strict: true })?.object;
    if (!target) return;
    const thtModule = game.modules.get("terrain-height-tools");
    if (!thtModule?.active || foundry.utils.isNewerVersion("0.3.3", thtModule.version)) {
      // @ts-expect-error not supposed to use a private method
      target._onHoverOut(event);
    } else {
      clearLos();
    }
  }

  function drawLos(target: Token) {
    const tokens = lancerActor?.getActiveTokens(true) ?? lancerItem?.actor?.getActiveTokens(true);
    const attacker = tokens?.shift();
    if (!attacker || attacker === target) return;
    terrainHeightTools!.drawLineOfSightRaysBetweenTokens(attacker, target);
  }

  function clearLos() {
    const thtModule = game.modules.get("terrain-height-tools");
    if (!thtModule?.active || foundry.utils.isNewerVersion("0.3.3", thtModule.version)) return;
    terrainHeightTools!.clearLineOfSightRays();
  }

  function escToCancel(_el: HTMLElement) {
    function escHandler(ev: KeyboardEvent) {
      if (ev.key === "Escape") {
        ev.preventDefault();
        dispatch("cancel");
      }
    }

    window.addEventListener("keydown", escHandler);
    return {
      destroy() {
        window.removeEventListener("keydown", escHandler);
      },
    };
  }

  function isAttack() {
    return kind === "attack";
  }

  function isTech() {
    if (!lancerItem) return title.toLowerCase() === "tech attack";
    if (lancerItem.is_mech_weapon()) return false;
    if (lancerItem.is_pilot_weapon()) return false;
    if (lancerItem.is_npc_feature() && lancerItem.system.type === NpcFeatureType.Weapon) return false;
    return true;
  }

  function isMelee() {
    if (!lancerItem || isTech()) return false;
    const result = lancerItem.currentProfile().type === WeaponType.Melee;
    return result;
  }

  function gritLabel() {
    // This is a tech attack
    if (isTech()) {
      if (lancerItem?.is_npc_feature() && lancerItem.system.type === NpcFeatureType.Tech) {
        return "Tech Item Base";
      }
      return "Tech Attack";
    }
    // Not a tech attack and we have an item. Base the label on the item type.
    if (lancerItem) {
      if (lancerItem.is_mech_weapon() || lancerItem.is_pilot_weapon()) {
        return "Grit";
      }
      if (lancerItem.is_npc_feature() && lancerItem.system.type === NpcFeatureType.Weapon) {
        return "Weapon Base";
      }
    }
    // Not a tech attack and we have no item. Base the label on the actor type.
    if (lancerActor) {
      if (lancerActor.is_npc()) {
        return "Tier";
      }
      if (lancerActor.is_mech() || lancerActor.is_pilot() || lancerActor.is_deployable()) {
        return "Grit";
      }
    }
    // Default fallback
    return "Grit";
  }

  function flatSign(val: number) {
    if (val > 0) return "+";
    return "";
  }

  function findProfile() {
    return lancerItem?.currentProfile() ?? { range: [], damage: [] };
  }

  function findRanges() {
    return lancerItem?.rangesFor([RangeType.Blast, RangeType.Burst, RangeType.Cone, RangeType.Line]) ?? [];
  }

  function deployTemplate(range: WeaponRangeTemplate["range"]) {
    const creator = lancerItem?.parent;
    const token = (creator?.token?.object ?? creator?.getActiveTokens().shift() ?? undefined) as LancerToken | undefined;
    const t = WeaponRangeTemplate.fromRange(range, token);
    if (!t) return;
    fade("out");
    t.document.updateSource({ [`flags.${game.system.id}.isAttack`]: true });
    t.placeTemplate()
      .catch(e => {
        console.warn(e);
        return;
      })
      .then(t => {
        if (t) targetsFromTemplate(t.id!);
        fade("in");
      });
  }
</script>

<form
  id="accdiff-hud"
  class="lancer lancer-hud accdiff window-content"
  use:escToCancel
  onsubmit={event => {
    event.preventDefault();
    submitted = true;
    dispatch("submit");
  }}
>
  {#if title != ""}
    <div class="lancer-header {isTech() ? 'lancer-tech' : 'lancer-weapon'} medium">
      {#if kind == "attack"}
        {#if isTech()}
          <i class="cci cci-tech-quick i--4 i--light"></i>
        {:else}
          <i class="cci cci-weapon i--4 i--light"></i>
        {/if}
      {:else if kind == "hase"}
        <i class="fas fa-dice-d20 i--4 i--light"></i>
      {/if}
      <span>{title}{rollerName}</span>
    </div>
  {/if}
  {#if profile}
    <MiniProfile {profile} />
  {/if}
  <div id="{kind}-accdiff-dialog" class="lancer-hud-body">
    <!-- Flat attack bonus -->
    {#if isAttack()}
      <label class="flexrow accdiff-weight lancer-border-primary" for="accdiff-flat-bonus"> Flat Modifier </label>
      <div class="accdiff-grid accdiff-flat-bonus">
        <div class="accdiff-other-grid">
          <span><b>{gritLabel()}:</b> {flatSign(base.grit)}{base.grit}</span>
        </div>
        <div class="accdiff-other-grid accdiff-flat-mod" style="position: relative">
          <!-- <PlusMinusInput bind:value={base.flatBonus} id="accdiff-flat-mod" /> -->
          <input class="accdiff-flat-mod__input" type="number" bind:value={base.flatBonus}>
          <button
            class="accdiff-flat-mod__plus"
            type="button"
            aria-label="Increase flat bonus"
            onclick={() => (base.flatBonus = base.flatBonus + 1)}
          >
            <i class="fas fa-plus"></i>
          </button>
          <button
            class="accdiff-flat-mod__minus"
            type="button"
            aria-label="Decrease flat bonus"
            onclick={() => (base.flatBonus = base.flatBonus - 1)}
          >
            <i class="fas fa-minus"></i>
          </button>
        </div>
        <div class="accdiff-other-grid">
          <span><b>Total:</b> {flatSign(flatTotal)}{flatTotal}</span>
        </div>
      </div>
    {/if}

    <div class="accdiff-grid accdiff-grid__section">
      <!-- Column Headers -->
      <div class="accdiff-grid__column">
        <h4 class="lancer-border-primary">
          <i class="cci cci-accuracy i--4" style="vertical-align: middle; border: none"></i>
          <span>Accuracy</span>
        </h4>
      </div>
      <div class="accdiff-grid__column">
        <h4 class="lancer-border-primary">
          <i class="cci cci-difficulty i--4" style="vertical-align: middle; border: none"></i>
          <span>Difficulty</span>
        </h4>
      </div>
    </div>

    <div class="accdiff-grid accdiff-grid__section">
      <!-- Accuracy column -->
      <div class="accdiff-grid__column">
        <HudCheckbox label="Accurate (+1)" bind:value={weapon.accurate} />
        <HudCheckbox label="Smart (*)" bind:value={weapon.smart} />
        {#if kind == "attack"}
          <HudCheckbox label="Seeking (*)" bind:value={weapon.seeking} />
          {#each accWeaponPlugins as plugin}
            <Plugin data={plugin} />
          {/each}
        {/if}
      </div>

      <!-- Difficulty column -->
      <div class="accdiff-grid__column">
        <HudCheckbox label="Inaccurate (-1)" bind:value={weapon.inaccurate} />
        <HudCheckbox label="Impaired (-1)" value={!!weapon.impaired} disabled />
        {#if kind == "attack" && !isTech()}
          {#if isMelee()}
            <HudCheckbox label="Thrown (*)" bind:value={weapon.thrown} />
          {/if}
          <HudCheckbox label="Engaged (-1)" bind:value={weapon.engaged} />
          {#each diffWeaponPlugins as plugin}
            <Plugin data={plugin} />
          {/each}
        {/if}
      </div>
    </div>

    {#if kind == "attack" && (Object.values(weapon.plugins).length > 0 || targets.length == 1)}
      <div transition:slide|global class="accdiff-grid accdiff-grid__section" style="width: 100%">
        <!-- Target-related Accuracy -->
        <div class="accdiff-grid__column">
          {#if targets.length == 1}
            <HudCheckbox style="grid-area: prone" label="Prone (+1)" bind:value={targets[0].prone} disabled />
            <HudCheckbox label="Stunned (EVA=5)" bind:value={targets[0].stunned} disabled />
            <HudCheckbox
              style="grid-area: lock-on"
              label="Lock On (+1)"
              checked={!!targets[0].usingLockOn}
              bind:value={targets[0].consumeLockOn}
              disabled={!targets[0].lockOnAvailable}
            />
            {#each accTargetPlugins as plugin}
              <Plugin data={plugin} />
            {/each}
          {/if}
        </div>

        <!-- Target-related Difficulty -->
        <div class="accdiff-grid__column">
          {#each diffTargetPlugins as plugin}
            <Plugin data={plugin} />
          {/each}
          <!-- Cover -->
          {#if useCover}
            <div class="grid-enforcement">
              {#if targets.length == 0}
                <div transition:slide>
                  <Cover
                    bind:cover={base.cover}
                    class="accdiff-base-cover flexcol"
                    disabled={weapon.seeking}
                  />
                </div>
              {:else if targets.length == 1}
                <div
                  role="radiogroup"
                  tabindex="0"
                  transition:slide
                  onmouseenter={ev => targetHoverIn(ev, targets[0].targetUuid)}
                  onmouseleave={ev => targetHoverOut(ev, targets[0].targetUuid)}
                >
                  <Cover
                    bind:cover={targets[0].cover}
                    class="accdiff-base-cover flexcol"
                    disabled={weapon.seeking}
                  />
                </div>
              {/if}
            </div>
          {/if}
        </div>
      </div>
    {/if}

    <!-- Total accuracy / Targets -->
    <div class="flexcol accdiff-grid">
      <div class="flexrow accdiff-grid__section" style="justify-content: space-evenly">
        <AccDiffInput bind:value={base.accuracy} id="accdiff-manual-adjust" />
      </div>
      {#if ranges && ranges.length > 0}
        <div class="accdiff-grid__section">
          <span class="accdiff-weight flex-center flexrow">Targeting</span>
          <div class="accdiff-ranges flexrow">
            {#each ranges as range}
              <button class="range-button" type="button" onclick={() => deployTemplate(range)}>
                <i class="cci cci-{range.type.toLowerCase()} i--4 i--light"></i>
                {ranges.length && ranges.length < 3 ? range.type.toUpperCase() : ""}
                {range.val}
              </button>
            {/each}
          </div>
        </div>
      {/if}
    </div>
    <div class="flexcol accdiff-footer lancer-border-primary">
      <div class="accdiff-total">
        {#if targets.length < 2}
          {#key targets.length}
            <div class="flexrow flex-center">
              <label
                transition:slide|global
                class="accdiff-weight total-label lancer-mini-header"
                for="total-display-0"
              >
                🞂 <span>Total
                  {#if targets.length > 0}
                    vs {targets[0].targetName}
                  {/if}</span> 🞀
              </label>
            </div>
          {/key}
        {/if}
        <div class="grid-enforcement">
          {#if targets.length == 0}
            <div class="flexrow flex-center accdiff-total">
              <Total target={base} id="total-display-0" />
            </div>
          {:else if targets.length == 1}
            <div
              role="presentation"
              class="flexrow flex-center accdiff-total"
              onmouseenter={ev => targetHoverIn(ev, targets[0].targetUuid)}
              onmouseleave={ev => targetHoverOut(ev, targets[0].targetUuid)}
            >
              <Total bind:target={targets[0]} id="total-display-0" onlyTarget={true} />
            </div>
          {:else}
            <div class="accdiff-weight accdiff-target-row">
              {#each targets as data, i (data.targetUuid)}
                <div
                  role="presentation"
                  in:slide|global={{ delay: 100, duration: 300 }}
                  out:slide|global={{ duration: 100 }}
                  animate:flip={{ duration: 200 }}
                  class="flexcol card accdiff-target"
                  onmouseenter={ev => targetHoverIn(ev, targets[i].targetUuid)}
                  onmouseleave={ev => targetHoverOut(ev, targets[i].targetUuid)}
                >
                  <label class="target-name flexrow lancer-mini-header" for={data.targetUuid}>
                    🞂<span>{targets[i].targetName}</span>🞀
                  </label>
                  <div class="accdiff-target-body">
                    <div class="flexrow accdiff-total">
                      <Total bind:target={targets[i]} id={`total-display-${i}`} />
                    </div>
                    <div class="flexrow">
                      <button
                        aria-label="Increase accuracy"
                        class="i--4 no-grow accdiff-button"
                        type="button"
                        onclick={() => (data.accuracy = data.accuracy + 1)}
                      >
                        <i class="cci cci-accuracy i--4" style="border: none"></i>
                      </button>
                      <input style="display: none" type="number" bind:value={data.accuracy} min="0">
                      {#if useCover}
                        <Cover
                          bind:cover={data.cover}
                          disabled={weapon.seeking}
                          class="accdiff-targeted-cover flexrow flex-center"
                          labelClass="i--2"
                        />
                      {:else}
                        <div></div>
                      {/if}
                      <input style="display: none" type="number" bind:value={data.difficulty} min="0">
                      <button
                        aria-label="Increase difficulty"
                        class="i--4 no-grow accdiff-button"
                        type="button"
                        onclick={() => (data.difficulty = data.difficulty + 1)}
                      >
                        <i class="cci cci-difficulty i--4" style="border: none"></i>
                      </button>
                    </div>
                  </div>
                </div>
              {/each}
            </div>
          {/if}
        </div>
      </div>
    </div>
  </div>
  <div class="lancer-hud-buttons flexrow">
    <button
      class="lancer-button lancer-secondary dialog-button submit default"
      data-button="submit"
      type="submit"
      use:focus
    >
      <i class="fas fa-check"></i>
      Roll
    </button>
    <button
      class="dialog-button cancel"
      data-button="cancel"
      type="button"
      onclick={() => {
        submitted = true;
        dispatch("cancel");
      }}
    >
      <i class="fas fa-times"></i>
      Cancel
    </button>
  </div>
</form>

